import math

def count_divisors(n):
    """Counts the number of divisors of n, tau(n)."""
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def get_sorted_divisors(n):
    """Returns a sorted list of all positive divisors of n."""
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def solve_problem():
    solutions = {} # Stores tau(n) for solutions found

    for n in range(1, 201):
        tau_n = count_divisors(n)

        if tau_n < 5:
            continue

        divisors = get_sorted_divisors(n)

        # We need at least 5 divisors for a, b, c to exist
        if len(divisors) < 5:
            # This case should not happen if tau_n >= 5, but good to check.
            continue

        # a = second smallest divisor (index 1 since divisors[0] is 1)
        a = divisors[1]
        # b = third smallest divisor (index 2)
        b = divisors[2]
        # c = fifth smallest divisor (index 4)
        c = divisors[4]

        # Check the condition: ab + ac + bc = n
        if a * b + a * c + b * c == n:
            solutions[tau_n] = solutions.get(tau_n, 0) + 1
            print(f"Solution found for n={n}. Divisors: {divisors}")
            print(f"  tau(n) = {tau_n}, a={a}, b={b}, c={c}")
            print(f"  Check: {a*b + a*c + b*c} == {n} (True)")

    print("\n--- Summary ---")
    if solutions:
        print("Tau(n) values for which solutions were found (count):", solutions)
    else:
        print("No solutions found for n <= 200.")

solve_problem()

import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    if n == 1:
        return 1
    count = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
        d += 1
    return count

